const{Vec3}=require('vec3');let lost=false,issue=null;const die=()=>{lost=true;bot.pathfinder.setGoal(null);bot.clearControlStates();};bot.on('death',die);bot.on('respawn',die);const dirs=[[1,0],[-1,0],[0,1],[0,-1]],count=n=>bot.inventory.items().filter(i=>i.name===n).reduce((a,i)=>a+i.count,0),full=b=>b&&b.boundingBox==='block'&&!/water|lava|fire|magma/.test(b.name);
function check(){if(lost||bot.health<14||bot.game.dimension!=='overworld')throw Error('life/body');}
async function dig(q){check();const b=bot.blockAt(q);if(!['dirt','stone','cobblestone','grass_block'].includes(b.name))throw Error('cut '+q+' '+b.name);if(/stone/.test(b.name)){const pick=bot.inventory.items().filter(i=>i.name.endsWith('_pickaxe')).sort((a,b)=>(a.durabilityUsed||0)-(b.durabilityUsed||0))[0];await bot.equip(pick,'hand');}else await bot.unequip('hand');let t;try{await Promise.race([bot.dig(b),new Promise((_,r)=>t=setTimeout(()=>{bot.stopDigging();r(Error('dig bound'));},6000))]);}finally{clearTimeout(t);}await bot.waitForTicks(12);check();}
async function craft(n,t=null,k=1){const r=bot.recipesFor(bot.registry.itemsByName[n].id,null,1,t)[0];if(!r)throw Error('recipe '+n);await bot.craft(r,k,t);await bot.waitForTicks(6);check();console.log('CRAFT_ACTUAL',n,count(n));}
async function move(q){const m=new Movements(bot);m.canDig=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=2;bot.pathfinder.setMovements(m);let t;try{await Promise.race([bot.pathfinder.goto(new goals.GoalBlock(q.x,q.y,q.z)),new Promise((_,r)=>t=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('move bound'));},5000))]);}finally{clearTimeout(t);bot.pathfinder.setGoal(null);bot.clearControlStates();}await bot.waitForTicks(5);check();if(!bot.entity.position.floored().equals(q))throw Error('actualmove');}
async function place(q,name,ref,face){const i=bot.inventory.items().find(i=>i.name===name);if(!i)throw Error('material '+name);await bot.equip(i,'hand');await bot.placeBlock(bot.blockAt(ref),face);await bot.waitForTicks(5);check();if(!full(bot.blockAt(q)))throw Error('actualplace '+q);}
async function seal(){check();bot.clearControlStates();await bot.waitForTicks(4);const p=bot.entity.position.floored();if(!full(bot.blockAt(p.offset(0,-1,0))))throw Error('sealfloor');const roof=p.offset(0,2,0);if(!full(bot.blockAt(roof))){const d=dirs.find(([x,z])=>full(bot.blockAt(roof.offset(x,0,z))));await place(roof,'dirt',roof.offset(d[0],0,d[1]),new Vec3(-d[0],0,-d[1]));}for(const[x,z]of dirs)for(const y of[0,1]){const q=p.offset(x,y,z);if(full(bot.blockAt(q)))continue;const n=['dirt','cobblestone','gravel','spruce_planks'].find(n=>count(n)>0);await place(q,n,q.offset(0,-1,0),new Vec3(0,1,0));}return full(bot.blockAt(roof))&&dirs.every(([x,z])=>[0,1].every(y=>full(bot.blockAt(p.offset(x,y,z)))));}
let closed=false;try{bot.pathfinder.setGoal(null);bot.clearControlStates();check();if(!bot.entity.position.floored().equals(new Vec3(35,66,80))||count('spruce_log')<2)throw Error('actualstarterorigin');await craft('spruce_planks',null,2);await craft('crafting_table');await craft('stick');await craft('wooden_pickaxe');
const floor=new Vec3(35,65,80);if(bot.blockAt(new Vec3(34,65,80)).boundingBox==='empty')await place(new Vec3(34,65,80),'dirt',floor,new Vec3(-1,0,0));if(!dirs.every(([x,z])=>[0,1].every(y=>full(bot.blockAt(new Vec3(35+x,65+y,80+z))))))throw Error('nextfloorcolumn notlined');await dig(floor);await bot.waitForTicks(8);if(Math.abs(bot.entity.position.y-65)>.15)throw Error('dropnotsettled');const table=new Vec3(35,67,80);await place(table,'crafting_table',new Vec3(36,67,80),new Vec3(-1,0,0));
for(const x of[36,37]){const q=new Vec3(x,65,80);if(!full(bot.blockAt(q.offset(0,-1,0)))||!full(bot.blockAt(q.offset(0,2,0))))throw Error('eastfloorroof');for(const dz of[-1,1])for(const y of[0,1])if(!full(bot.blockAt(q.offset(0,y,dz))))throw Error('eastoutside');}if(![65,66].every(y=>full(bot.blockAt(new Vec3(38,y,80)))))throw Error('eastcap');
await dig(new Vec3(36,65,80));await dig(new Vec3(36,66,80));await move(new Vec3(36,65,80));await dig(new Vec3(37,65,80));if(count('cobblestone')<3)throw Error('threeactualcobblemissing');await craft('stone_pickaxe',bot.blockAt(table));await dig(new Vec3(37,66,80));await move(new Vec3(37,65,80));
}catch(e){issue=e.message;console.log('BOOTSTRAP_ISSUE',issue);}finally{try{if(!lost)closed=await seal();}finally{bot.clearControlStates();bot.pathfinder.setGoal(null);bot.removeListener('death',die);bot.removeListener('respawn',die);}}
return{issue,lost,closed,position:bot.entity.position,health:bot.health,food:bot.food,inventory:bot.inventory.items().map(i=>[i.name,i.count,i.durabilityUsed])};
